109	    /** Move a claim to another status; a change its status does not allow, or of a claim dated in a closed
110	     * period, is refused. A settle by a clerk of a claim whose due is above the clerk limit sends it PENDING a
111	     * steward instead. */
112	    @Transactional
113	    public Claim changeStatus(String user, String sheetId, Long id, ClaimStatus next) {
114	        sheets.today(sheetId); // the sheet must exist
115	        // Locking the sheet before taking the number opens claims one at a time; a refused open rolls back
116	        // and gives the number back.
117	        if (next == ClaimStatus.OPEN) {
118	            sheets.lock(sheetId);
119	        }
120	        Claim claim = claims.findByIdAndSheetId(id, sheetId)
121	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim."));
122	        String number = next == ClaimStatus.OPEN ? nextNumber(sheetId, claim) : null;
123	        requireOpenPeriod(sheetId, claim.getDate());
124	        if (!claim.getStatus().canBecome(next)) {
125	            throw new ResponseStatusException(HttpStatus.CONFLICT,
126	                    "A " + claim.getStatus() + " claim cannot become " + next + ".");
127	        }
128	        // A deferred claim cannot be settled until the sheet's today reaches the date it is deferred until.
129	        if (next == ClaimStatus.SETTLED && claim.deferredOn(sheets.today(sheetId))) {
130	            throw new ResponseStatusException(HttpStatus.CONFLICT,
131	                    "The claim is deferred until " + claim.getDeferredUntil() + ".");
132	        }
133	        // Four eyes: whoever opened a claim cannot also settle it.
134	        if (next == ClaimStatus.SETTLED && user.equals(claim.getOpenedBy())) {
135	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "The user who opened a claim cannot settle it.");
136	        }
137	        Person person = requirePerson(sheetId, claim.getPersonId());
138	        BigDecimal due = rollup.dueOf(claim, person);
139	        // A clerk settles only a claim whose due is within the sheet's clerk limit; above it, a steward must
140	        // approve it.
141	        if (next == ClaimStatus.SETTLED && !settings.maySettle(sheetId, user, due)) {
142	            next = ClaimStatus.PENDING;
143	        }
144	        Snapshot before = rollup.snapshot(sheetId);
145	        claim.setStatus(next);
146	        if (next == ClaimStatus.OPEN) {
147	            claim.setNumber(number);
148	            claim.setOpenedBy(user);
149	        }
150	        // A voided claim's line carries the number it had.
151	        String entry = entry(EVENTS.get(next), user, person, claim);
152	        if (next == ClaimStatus.SETTLED) {
153	            // Settling fixes the due at the figure the claim has: the one its last statement bound it to, else
154	            // the rate its grade has on its date; with no figure it stays live. The late charge it has (taken
155	            // while it is still OPEN) is frozen in.
156	            entry += settle(claim, due);
157	        }
158	        logStatus(user, sheets.today(sheetId), claim, person);
159	        claims.flush();
160	        audit.recordOnCommit(entry);
161	        rollup.recordChanges(user, sheetId, before);
162	        return claim;
163	    }
164	
165	    /** A steward approves a PENDING claim: it is SETTLED at the due it has now, its live figure with any late
166	     * charge, frozen. The user who opened it cannot approve it. */
167	    @Transactional
168	    public Claim approve(String user, String sheetId, Long id) {
169	        Claim claim = requirePending(user, sheetId, id);
170	        if (user.equals(claim.getOpenedBy())) {
171	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "The user who opened a claim cannot approve it.");
172	        }
173	        Person person = requirePerson(sheetId, claim.getPersonId());
174	        Snapshot before = rollup.snapshot(sheetId);
175	        BigDecimal due = rollup.dueOf(claim, person);
176	        claim.setStatus(ClaimStatus.SETTLED);
177	        String entry = entry("CLAIM_APPROVED", user, person, claim) + settle(claim, due);
178	        logStatus(user, sheets.today(sheetId), claim, person);
179	        claims.flush();
180	        audit.recordOnCommit(entry);
181	        rollup.recordChanges(user, sheetId, before);
182	        return claim;
183	    }
184	
185	    /** A steward re-settles a SETTLED claim: it is frozen again at the figure it would have today as an OPEN
186	     * claim bound by no statement, at today's rates, grades, floor and late charge. Refused for anyone else, a
187	     * claim of any other status, or one dated in a closed period. */
188	    @Transactional
189	    public Claim resettle(String user, String sheetId, Long id) {
190	        sheets.today(sheetId); // the sheet must exist
191	        Claim claim = claims.findByIdAndSheetId(id, sheetId)
192	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim."));
193	        requireOpenPeriod(sheetId, claim.getDate());
194	        if (claim.getStatus() != ClaimStatus.SETTLED) {
195	            throw new ResponseStatusException(HttpStatus.CONFLICT, "Only a SETTLED claim can be re-settled.");
196	        }
197	        settings.requireSteward(sheetId, user);
198	        Person person = requirePerson(sheetId, claim.getPersonId());
199	        Snapshot before = rollup.snapshot(sheetId);
200	        BigDecimal old = rollup.dueOf(claim, person);
201	        BigDecimal now = rollup.openDueOf(claim, person);
202	        claim.setSettledDue(now);
203	        logStatus(user, sheets.today(sheetId), claim, person);
204	        claims.flush();
205	        audit.recordOnCommit(entry("CLAIM_RESETTLED", user, person, claim) + " old=" + figure(old) + " new="
206	                + figure(now));
207	        rollup.recordChanges(user, sheetId, before);
208	        return claim;
209	    }
210	
211	    /** A figure with two decimals, or n/a. */
212	    private static String figure(BigDecimal due) {
213	        return due != null ? due.setScale(2).toPlainString() : "n/a";
214	    }
215	
216	    /** Defer an OPEN claim until a date after the sheet's today: until then it counts in no total, is not overdue,
217	     * cannot be settled and is left unbound by a statement. A claim that is not OPEN, a date not after today, or
218	     * a claim dated in a closed period, is refused. */
219	    @Transactional
220	    public Claim defer(String user, String sheetId, Long id, LocalDate until) {
221	        LocalDate today = sheets.today(sheetId);
222	        Claim claim = claims.findByIdAndSheetId(id, sheetId)
223	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim."));
224	        requireOpenPeriod(sheetId, claim.getDate());
225	        if (claim.getStatus() != ClaimStatus.OPEN) {
226	            throw new ResponseStatusException(HttpStatus.CONFLICT, "Only an OPEN claim can be deferred.");
227	        }
228	        if (!until.isAfter(today)) {
229	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "A claim is deferred to a date after today.");
230	        }
231	        Person person = requirePerson(sheetId, claim.getPersonId());
232	        Snapshot before = rollup.snapshot(sheetId);
233	        claim.setDeferredUntil(until);
234	        claims.flush();
235	        audit.recordOnCommit(entry("CLAIM_DEFERRED", user, person, claim) + " until=" + until);
236	        rollup.recordChanges(user, sheetId, before);
237	        return claim;
238	    }
239	
240	    /** A steward rejects a PENDING claim with a reason: it is OPEN again, bound again by its person's last
241	     * statement if that statement included it. */
242	    @Transactional
243	    public Claim reject(String user, String sheetId, Long id, String reason) {
244	        Claim claim = requirePending(user, sheetId, id);
245	        Person person = requirePerson(sheetId, claim.getPersonId());
246	        Snapshot before = rollup.snapshot(sheetId);
247	        claim.setStatus(ClaimStatus.OPEN);
248	        logStatus(user, sheets.today(sheetId), claim, person);
249	        claims.flush();
250	        audit.recordOnCommit(entry("CLAIM_REJECTED", user, person, claim) + " reason=" + reason.trim());
251	        rollup.recordChanges(user, sheetId, before);
252	        return claim;
253	    }
254	
255	    /** A steward moves a DRAFT, OPEN or PENDING claim to another person on the sheet. It keeps its number and
256	     * date but loses any figure a statement bound it to: it is live again until its new person's next statement.
257	     * One dated in a closed period, a correction (which names a settled claim of its own person), or one dated
258	     * after its new person is retired, is refused. */
259	    @Transactional
260	    public Claim reassign(String user, String sheetId, Long id, Long toPersonId) {
261	        sheets.today(sheetId); // the sheet must exist
262	        Claim claim = claims.findByIdAndSheetId(id, sheetId)
263	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim."));
264	        settings.requireSteward(sheetId, user);
265	        requireOpenPeriod(sheetId, claim.getDate());
266	        if (claim.getStatus() != ClaimStatus.DRAFT && !claim.getStatus().isOpen()) {
267	            throw new ResponseStatusException(HttpStatus.CONFLICT,
268	                    "A " + claim.getStatus() + " claim cannot be moved.");
269	        }
270	        if (claim.isCorrection()) {
271	            throw new ResponseStatusException(HttpStatus.CONFLICT, "A correction cannot be moved.");
272	        }
273	        Person from = requirePerson(sheetId, claim.getPersonId());
274	        Person to = requirePerson(sheetId, toPersonId);
275	        if (from.getId().equals(to.getId())) {
276	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "The claim is already that person's.");
277	        }
278	        if (to.retiredOn(claim.getDate())) {
279	            throw new ResponseStatusException(HttpStatus.GONE,
280	                    to.getName() + " is retired from " + to.getRetiredFrom() + ".");
281	        }
282	        Snapshot before = rollup.snapshot(sheetId);
283	        claim.setPersonId(to.getId());
284	        claim.unbind();
285	        claims.flush();
286	        audit.recordOnCommit(entry("CLAIM_REASSIGNED", user, to, claim) + " from=" + from.getName() + " to="
287	                + to.getName());
288	        rollup.recordChanges(user, sheetId, before);
289	        return claim;
290	    }
291	
292	    /** The PENDING claim a steward acts on; refused when it is not on the sheet, not PENDING, dated in a closed
293	     * period, or the user is not a steward. */
294	    private Claim requirePending(String user, String sheetId, Long id) {
295	        sheets.today(sheetId); // the sheet must exist
296	        Claim claim = claims.findByIdAndSheetId(id, sheetId)
297	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim."));
298	        requireOpenPeriod(sheetId, claim.getDate());
299	        if (claim.getStatus() != ClaimStatus.PENDING) {
300	            throw new ResponseStatusException(HttpStatus.CONFLICT, "Only a PENDING claim can be approved or rejected.");
301	        }
302	        settings.requireSteward(sheetId, user);
303	        return claim;
304	    }
305	
306	    /** Log the status a claim has now, by the user on the sheet's today, with its due as computed now. */
307	    private void logStatus(String user, LocalDate today, Claim claim, Person person) {
308	        BigDecimal due = rollup.dueOf(claim, person);
309	        claim.logStatus(user, today, due != null ? due.setScale(2).toPlainString() : "n/a");
310	    }
311	
312	    /** Fix a claim's due at the given figure (none stays live), giving the end of its audit line. */
313	    private static String settle(Claim claim, BigDecimal due) {
314	        claim.setSettledDue(due);
315	        return " due=" + (due != null ? due.toPlainString() : "n/a");
316	    }
317	
318	    /** What opening (or settling) claims together did: how many went through and were refused, and the claims
319	     * that went through. */
320	    public record OpenedAll(int opened, int refused, List<Claim> claims) {}
321	
322	    /** Open the given claims of the sheet one at a time, in list order: people in the order they were added,
323	     * each one's claims newest first. Each is opened, and numbered, as {@link #changeStatus} would open it on its
324	     * own; one that cannot be opened (or is not on the sheet) is refused and left as it is. */
325	    public OpenedAll openAll(String user, String sheetId, List<Long> ids) {
326	        return changeAll(user, sheetId, ids, ClaimStatus.OPEN);
327	    }
328	
329	    /** Settle the given claims of the sheet one at a time, in list order, each as {@link #changeStatus} would
330	     * settle it on its own: one a clerk sends PENDING counts as settled; one that cannot be settled (or is not on
331	     * the sheet) is refused and left as it is. */
332	    public OpenedAll settleAll(String user, String sheetId, List<Long> ids) {
333	        return changeAll(user, sheetId, ids, ClaimStatus.SETTLED);
334	    }
335	
336	    /** Move the given claims to a status one at a time, in list order: people in the order they were added, each
337	     * one's claims newest first, each in its own transaction; one that is refused is left as it is. */
338	    private OpenedAll changeAll(String user, String sheetId, List<Long> ids, ClaimStatus next) {
339	        Set<Long> wanted = new HashSet<>(ids);
340	        List<Claim> chosen = transaction.execute(status -> {
341	            sheets.today(sheetId); // the sheet must exist
342	            Map<Long, Integer> personOrder = new HashMap<>();
343	            for (Person person : people.findBySheetIdOrderByIdAsc(sheetId)) {
344	                personOrder.put(person.getId(), personOrder.size());
345	            }
346	            return claims.findBySheetIdOrderByIdDesc(sheetId).stream()
347	                    .filter(c -> wanted.contains(c.getId()))
348	                    .sorted(Comparator.comparing((Claim c) -> personOrder.getOrDefault(c.getPersonId(), Integer.MAX_VALUE)))
349	                    .toList();
350	        });
351	        List<Claim> changed = new ArrayList<>();
352	        for (Claim claim : chosen) {
353	            try {
354	                changed.add(transaction.execute(status -> changeStatus(user, sheetId, claim.getId(), next)));
355	            } catch (ResponseStatusException refused) {
356	                // Left as it is: its transaction rolled back, writing nothing.
357	            }
358	        }
359	        return new OpenedAll(changed.size(), wanted.size() - changed.size(), changed);
360	    }
361	
362	    /** The sequence a claim in no period is numbered in, with period numbering. */
363	    private static final String NO_PERIOD = "X";
364	
365	    private static final Map<ClaimStatus, String> EVENTS = Map.of(
366	            ClaimStatus.OPEN, "CLAIM_OPENED",
367	            ClaimStatus.PENDING, "CLAIM_PENDING",
368	            ClaimStatus.SETTLED, "CLAIM_SETTLED",
369	            ClaimStatus.VOID, "CLAIM_VOIDED");
370	
371	    /** The figure a claim has now: what it was settled at, else what its person's last statement bound it to,
372	     * else what is due at the rate of the grade its person has on its date; none when that is n/a. */
373	    public BigDecimal figureOf(Claim claim, Person person) {
374	        return rollup.figureOf(claim, person);
375	    }
376	
377	    /** The number a claim opened now takes: the sheet's next number or, with period numbering in force, the next
378	     * in its period's own sequence, <period name>-<n>, or X-<n> for a claim in no period. */
379	    private String nextNumber(String sheetId, Claim claim) {
380	        if (!sheets.numbersByPeriod(sheetId)) {
381	            return String.valueOf(sheets.nextClaimNumber(sheetId));
382	        }
383	        String prefix = periods.periodOf(sheetId, claim.getDate()).map(Period::getName).orElse(NO_PERIOD) + "-";
384	        int last = 0;
385	        for (Claim other : claims.findBySheetIdOrderByIdDesc(sheetId)) {
386	            String number = other.getNumber();
387	            if (number != null && number.startsWith(prefix)) {
388	                String rest = number.substring(prefix.length());
389	                if (rest.matches("\\d{1,9}")) {
390	                    last = Math.max(last, Integer.parseInt(rest));
391	                }
392	            }
393	        }
394	        return prefix + (last + 1);
395	    }
396	
397	    /** The number a claim of this amount corrects: none unless the amount is negative, when it must name a
398	     * SETTLED claim of the same person, or the claim is refused. */
399	    private String correctedBy(String sheetId, Long personId, BigDecimal amount, String corrects) {
400	        if (amount.signum() >= 0) {
401	            return null;
402	        }
403	        String named = corrects == null ? null : corrects.trim();
404	        boolean settled = named != null && claims.findBySheetIdAndPersonId(sheetId, personId).stream()
405	                .anyMatch(c -> named.equals(c.getNumber()) && c.getStatus() == ClaimStatus.SETTLED);
406	        if (!settled) {
407	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
408	                    "A correction must name a settled claim of the same person.");
409	        }
410	        return named;
411	    }
412	
413	    /** Refuse a change to a claim dated in a closed period. Locks the sheet first, so a period cannot close
414	     * while the change is made. */
415	    private void requireOpenPeriod(String sheetId, LocalDate date) {
416	        sheets.lock(sheetId);
417	        periods.requireOpen(sheetId, date);
418	    }
419	
420	    /** Refuse a claim dated after its person's retirement. */
421	    private static void requireNotRetired(Person person, LocalDate date) {
422	        if (person.retiredOn(date)) {
423	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT,
424	                    person.getName() + " is retired from " + person.getRetiredFrom() + ".");
425	        }
426	    }
427	
428	    private Person requirePerson(String sheetId, Long personId) {
429	        return people.findByIdAndSheetId(personId, sheetId)
430	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person."));
431	    }
432	
433	    /** The amount is written as the screen shows it, with two decimals; the date as yyyy-mm-dd; a
434	     * claim with a number ends with it. */
435	    private static String entry(String event, String user, Person person, Claim claim) {
436	        return event + " sheet=" + claim.getSheetId() + " by=" + user + " person=" + person.getName()
437	                + " amount=" + claim.getAmount().setScale(2).toPlainString() + " date=" + claim.getDate()
438	                + (claim.getNumber() != null ? " number=" + claim.getNumber() : "");
439	    }
440	
441	    private static String noteOf(String note) {
442	        return note == null ? "" : note.trim();
443	    }
444	}
