import { Injectable, computed, signal } from '@angular/core';
import { Dated, valueOn } from './dated';

/** The floor a sheet starts with, in force before every from-date. */
export const DEFAULT_FLOOR = '1.00';

// The active sheet's floor, the least a claim's live due comes to, dated: set by the settings when they are
// read or saved, and read wherever a due is shown, as the floor in force on a claim's date.
@Injectable({ providedIn: 'root' })
export class SheetFloor {
  private readonly history = signal<readonly Dated[]>([]);
  /** The floor in force on a date. */
  readonly on = computed(() => {
    const history = this.history();
    return (date: string): string => valueOn(history, date, DEFAULT_FLOOR) ?? DEFAULT_FLOOR;
  });

  set(history: readonly Dated[]): void {
    this.history.set(history);
  }
}
import { Injectable, computed, inject, signal } from '@angular/core';
import { Session } from '../../core/session';
import { Dated, valueOn } from './dated';

// The active sheet's cap, the most a person's due-total comes to (null for none), dated: set by the settings
// when they are read or saved, and read wherever a due-total is shown, as the cap in force on the sheet's today.
@Injectable({ providedIn: 'root' })
export class SheetCap {
  private readonly session = inject(Session);
  private readonly history = signal<readonly Dated[]>([]);
  /** The cap in force on the sheet's today. */
  readonly value = computed(() => {
    const today = this.session.today();
    return today === null ? null : valueOn(this.history(), today, null);
  });

  set(history: readonly Dated[]): void {
    this.history.set(history);
  }
}
/** A value a dated setting has from a from-date (yyyy-mm-dd; null for the beginning of time); null for none. */
export interface Dated {
  from: string | null;
  value: string | null;
}

/** The value a dated setting has in force on a date: the one with the latest from-date on or before it, else
 * `starting`, the value a sheet starts with. */
export function valueOn<T extends string | null>(history: readonly Dated[], date: string, starting: T): string | T {
  let found: Dated | undefined;
  for (const d of history) {
    if (d.from !== null && d.from > date) continue;
    if (found === undefined || (found.from ?? '') <= (d.from ?? '')) found = d;
  }
  return found === undefined ? starting : (found.value as string | T);
}
import { HttpClient } from '@angular/common/http';
import { Injectable, inject } from '@angular/core';
import { Observable } from 'rxjs';
import { Session } from '../../core/session';
import { Dated } from './dated';

/** The roles a user name can have on a sheet; any name without one is a clerk. */
export const ROLES = ['clerk', 'steward'] as const;
export type Role = (typeof ROLES)[number];

export interface RoleGiven {
  user: string;
  role: Role;
}

/** The keys of the settings that carry a figure, each dated. */
export const DATED_KEYS = ['clerk-limit', 'floor', 'terms', 'terms-A', 'terms-B', 'terms-C', 'late-pct', 'cap'] as const;
export type DatedKey = (typeof DATED_KEYS)[number];

/** The settings in force on the sheet's today; `dated` has, for each setting that carries a figure, every value
 * recorded for it by from-date. */
export interface Settings {
  /** The highest due a clerk may settle, with two decimals; null for no limit. */
  clerkLimit: string | null;
  /** The least a claim's live due comes to, with two decimals. */
  floor: string;
  /** The days after its date a claim is due by. */
  terms: number;
  /** Each grade's own terms in days; null when the grade uses the sheet's terms. */
  termsA: number | null;
  termsB: number | null;
  termsC: number | null;
  /** What an overdue claim gains of its figure for every full 30 days overdue, with two decimals. */
  latePct: string;
  /** The date (yyyy-mm-dd) a claim dated before rounds half up, on or after half to even; null for the
   * sheet's today. */
  policyDate: string | null;
  /** The date (yyyy-mm-dd) from which, while the sheet's today is on or after it, a claim opened is numbered
   * within its period; null when off. */
  periodNumberingFrom: string | null;
  /** The most a person's due-total comes to, with two decimals; null for none. */
  cap: string | null;
  dated: Record<DatedKey, Dated[]>;
}

// A sheet's settings: the role each user name has, its clerk limit, its floor, its terms and each grade's, its late percent, its policy date, its period numbering date and its cap (those that carry a figure dated), read and changed through the
// server.
@Injectable({ providedIn: 'root' })
export class SettingsApi {
  private readonly http = inject(HttpClient);
  private readonly session = inject(Session);

  roles(sheetId: string): Observable<RoleGiven[]> {
    return this.http.get<RoleGiven[]>(`${this.url(sheetId)}/roles`, { headers: this.headers() });
  }

  setRole(sheetId: string, user: string, role: string): Observable<RoleGiven> {
    return this.http.put<RoleGiven>(`${this.url(sheetId)}/roles`, { user, role }, { headers: this.headers() });
  }

  get(sheetId: string): Observable<Settings> {
    return this.http.get<Settings>(`${this.url(sheetId)}/settings`, { headers: this.headers() });
  }

  /** Save the settings given; one left out is left as it is. A setting that carries a figure is recorded from
   * its from-date (`floorFrom` and so on), or from the sheet's today when none is given. */
  save(
    sheetId: string,
    settings: { clerkLimit?: string; floor?: string; terms?: string; termsA?: string; termsB?: string;
      termsC?: string; latePct?: string; policyDate?: string; periodNumberingFrom?: string; cap?: string;
      clerkLimitFrom?: string; floorFrom?: string; termsFrom?: string; termsAFrom?: string; termsBFrom?: string;
      termsCFrom?: string; latePctFrom?: string; capFrom?: string; },
  ): Observable<Settings> {
    return this.http.put<Settings>(`${this.url(sheetId)}/settings`, settings, { headers: this.headers() });
  }

  private url(sheetId: string): string {
    return `/api/sheets/${encodeURIComponent(sheetId)}`;
  }

  private headers(): Record<string, string> {
    return { 'X-User': this.session.user() ?? '' };
  }
}
