1	import { Component, DestroyRef, computed, inject, signal } from '@angular/core';
2	import { toObservable } from '@angular/core/rxjs-interop';
3	import { FormControl, FormGroup, ReactiveFormsModule } from '@angular/forms';
4	import { Subject, catchError, concatMap, forkJoin, map, of, switchMap } from 'rxjs';
5	import { Session } from '../../core/session';
6	import { DATED_KEYS, DatedKey, ROLES, RoleGiven, Settings as SheetSettings, SettingsApi } from './settings-api';
7	import { valueOn } from './dated';
8	import { DEFAULT_FLOOR, SheetFloor } from './sheet-floor';
9	import { DEFAULT_LATE_PCT, SheetLatePct } from './sheet-late-pct';
10	import { SheetCap } from './sheet-cap';
11	import { SheetPolicyDate } from './sheet-policy-date';
12	
13	/** The terms a sheet starts with, in days. */
14	const DEFAULT_TERMS = 14;
15	/** The grades that can have terms of their own. */
16	const GRADES = ['A', 'B', 'C'] as const;
17	type GradeTermsKey = `terms${(typeof GRADES)[number]}`;
18	/** The settings in the form that carry a figure, each saved from a from-date, by the key the sheet keeps them by. */
19	const DATED_FIELDS = {
20	  clerkLimit: 'clerk-limit',
21	  floor: 'floor',
22	  terms: 'terms',
23	  termsA: 'terms-A',
24	  termsB: 'terms-B',
25	  termsC: 'terms-C',
26	  latePct: 'late-pct',
27	  cap: 'cap',
28	} as const satisfies Record<string, DatedKey>;
29	type DatedField = keyof typeof DATED_FIELDS;
30	type FromField = `${DatedField}From`;
31	const LIMIT = /^\d{1,10}(\.\d{1,2})?$/;
32	const DAYS = /^\d{1,5}$/;
33	const PCT = /^\d{1,5}(\.\d{1,2})?$/;
34	const DATE = /^\d{4}-\d{2}-\d{2}$/;
35	type SettingsFormValue = {
36	  clerkLimit: string;
37	  floor: string;
38	  terms: string;
39	  termsA: string;
40	  termsB: string;
41	  termsC: string;
42	  latePct: string;
43	  policyDate: string;
44	  periodNumberingFrom: string;
45	  cap: string;
46	};
47	
48	const NO_SETTINGS: SheetSettings = {
49	  clerkLimit: null,
50	  floor: DEFAULT_FLOOR,
51	  terms: DEFAULT_TERMS,
52	  termsA: null,
53	  termsB: null,
54	  termsC: null,
55	  latePct: DEFAULT_LATE_PCT,
56	  policyDate: null,
57	  periodNumberingFrom: null,
58	  cap: null,
59	  dated: Object.fromEntries(DATED_KEYS.map((k) => [k, []])) as unknown as SheetSettings['dated'],
60	};
61	
62	// The sheet's settings: the role each user name has (clerk unless given another) with the form that
63	// gives one, the clerk limit, the highest due a clerk may settle (blank for no limit), and the floor, the
64	// least a claim's live due comes to, the terms, the days after its date a claim is due by (fixed when it is
65	// added), and each grade's own terms (blank for the sheet's), and the late
66	// percent, what an overdue claim gains of its figure for every full 30 days overdue, and the policy date (blank
67	// for the sheet's today), before which a claim's date rounds half up, on or after half to even, and the period
68	// numbering date (blank for off), from which a claim opened is numbered within its period, and the cap (blank
69	// for none), the most a person's due-total comes to. The settings that carry a figure are dated: each is saved
70	// from its from-date (blank for the sheet's today), and the value in force on the sheet's today is shown. Saving
71	// sends only the settings changed in the form (the clerk limit when none was).
72	@Component({
73	  selector: 'app-settings',
74	  imports: [ReactiveFormsModule],
75	  template: `
76	    <section aria-labelledby="settings-heading" data-testid="settings">
77	      <h2 id="settings-heading">Settings</h2>
78	      <form [formGroup]="settingsForm" (ngSubmit)="save()" (focusin)="focused($event)" data-testid="settings-form">
79	        <label for="setting-clerk-limit">Clerk limit (blank for none)</label>
80	        <input
81	          id="setting-clerk-limit"
82	          data-testid="setting-clerk-limit"
83	          inputmode="decimal"
84	          formControlName="clerkLimit"
85	        />
86	        <label for="setting-clerk-limit-from">Clerk limit from (yyyy-mm-dd, blank for the sheet's today)</label>
87	        <input id="setting-clerk-limit-from" data-testid="setting-clerk-limit-from" formControlName="clerkLimitFrom" />
88	        <label for="setting-floor">Floor</label>
89	        <input id="setting-floor" data-testid="setting-floor" inputmode="decimal" formControlName="floor" />
90	        <label for="setting-floor-from">Floor from (yyyy-mm-dd, blank for the sheet's today)</label>
91	        <input id="setting-floor-from" data-testid="setting-floor-from" formControlName="floorFrom" />
92	        <label for="setting-terms">Terms (days)</label>
93	        <input id="setting-terms" data-testid="setting-terms" inputmode="numeric" formControlName="terms" />
94	        <label for="setting-terms-from">Terms from (yyyy-mm-dd, blank for the sheet's today)</label>
95	        <input id="setting-terms-from" data-testid="setting-terms-from" formControlName="termsFrom" />
96	        @for (g of grades; track g) {
97	          <label [for]="'setting-terms-' + g">Terms for grade {{ g }} (days, blank for the sheet's)</label>
98	          <input
99	            [id]="'setting-terms-' + g"
100	            [attr.data-testid]="'setting-terms-' + g"
101	            inputmode="numeric"
102	            [formControlName]="'terms' + g"
103	          />
104	          <label [for]="'setting-terms-' + g + '-from'">Terms for grade {{ g }} from (yyyy-mm-dd, blank for the sheet's today)</label>
105	          <input
106	            [id]="'setting-terms-' + g + '-from'"
107	            [attr.data-testid]="'setting-terms-' + g + '-from'"
108	            [formControlName]="'terms' + g + 'From'"
109	          />
110	        }
111	        <label for="setting-late-pct">Late percent (per full 30 days overdue)</label>
112	        <input id="setting-late-pct" data-testid="setting-late-pct" inputmode="decimal" formControlName="latePct" />
113	        <label for="setting-late-pct-from">Late percent from (yyyy-mm-dd, blank for the sheet's today)</label>
114	        <input id="setting-late-pct-from" data-testid="setting-late-pct-from" formControlName="latePctFrom" />
115	        <label for="setting-policy-date">Policy date (yyyy-mm-dd, blank for the sheet's today)</label>
116	        <input id="setting-policy-date" data-testid="setting-policy-date" formControlName="policyDate" />
117	        <label for="setting-period-numbering-from">Period numbering from (yyyy-mm-dd, blank for off)</label>
118	        <input
119	          id="setting-period-numbering-from"
120	          data-testid="setting-period-numbering-from"
121	          formControlName="periodNumberingFrom"
122	        />
123	        <label for="setting-cap">Cap (blank for none)</label>
124	        <input id="setting-cap" data-testid="setting-cap" inputmode="decimal" formControlName="cap" />
125	        <label for="setting-cap-from">Cap from (yyyy-mm-dd, blank for the sheet's today)</label>
126	        <input id="setting-cap-from" data-testid="setting-cap-from" formControlName="capFrom" />
127	        <button type="submit" data-testid="settings-save">Save settings</button>
128	      </form>
129	      @if (settingsError(); as e) {
130	        <p role="alert" data-testid="settings-error">{{ e }}</p>
131	      }
132	      <p>
133	        Clerk limit in force:
134	        <span data-testid="setting-clerk-limit-current">{{ inForce().clerkLimit ?? '' }}</span>
135	      </p>
136	      <p>
137	        Floor in force:
138	        <span data-testid="setting-floor-current">{{ inForce().floor }}</span>
139	      </p>
140	      <p>
141	        Terms in force:
142	        <span data-testid="setting-terms-current">{{ inForce().terms }}</span>
143	      </p>
144	      @for (g of grades; track g) {
145	        <p>
146	          Terms for grade {{ g }} in force:
147	          <span [attr.data-testid]="'setting-terms-' + g + '-current'">{{ inForce()[gradeKey(g)] ?? '' }}</span>
148	        </p>
149	      }
150	      <p>
151	        Late percent in force:
152	        <span data-testid="setting-late-pct-current">{{ inForce().latePct }}</span>
153	      </p>
154	      <p>
155	        Policy date in force:
156	        <span data-testid="setting-policy-date-current">{{ settings().policyDate ?? '' }}</span>
157	      </p>
158	      <p>
159	        Period numbering from:
160	        <span data-testid="setting-period-numbering-from-current">{{ settings().periodNumberingFrom ?? '' }}</span>
161	      </p>
162	      <p>
163	        Cap in force:
164	        <span data-testid="setting-cap-current">{{ inForce().cap ?? '' }}</span>
165	      </p>
166	      <form [formGroup]="roleForm" (ngSubmit)="setRole()" data-testid="role-form">
167	        <label for="role-form-user">User</label>
168	        <input id="role-form-user" data-testid="role-form-user" formControlName="user" />
169	        <label for="role-form-role">Role ({{ roleNames }})</label>
170	        <input id="role-form-role" data-testid="role-form-role" formControlName="role" />
171	        <button type="submit" data-testid="role-form-submit">Set role</button>
172	      </form>
173	      @if (roleError(); as e) {
174	        <p role="alert" data-testid="role-form-error">{{ e }}</p>
175	      }
176	      <table data-testid="role-list">
177	        <caption>Roles (anyone else is a clerk)</caption>
178	        <thead>
179	          <tr>
180	            <th scope="col">User</th>
181	            <th scope="col">Role</th>
182	          </tr>
183	        </thead>
184	        <tbody>
185	          @for (r of roles(); track r.user) {
186	            <tr [attr.data-testid]="'role-row-' + r.user">
187	              <td data-testid="role-user">{{ r.user }}</td>
188	              <td data-testid="role-value">{{ r.role }}</td>
189	            </tr>
190	          }
191	        </tbody>
192	      </table>
193	    </section>
194	  `,
195	})
196	export class Settings {
197	  private readonly session = inject(Session);
198	  private readonly api = inject(SettingsApi);
199	  private readonly floor = inject(SheetFloor);
200	  private readonly latePct = inject(SheetLatePct);
201	  private readonly policyDate = inject(SheetPolicyDate);
202	  private readonly cap = inject(SheetCap);
203	
204	  protected readonly roleNames = ROLES.join(' or ');
205	  protected readonly grades = GRADES;
206	  protected readonly roles = signal<RoleGiven[]>([]);
207	  protected readonly settings = signal<SheetSettings>(NO_SETTINGS);
208	  /** The value each setting that carries a figure has in force on the sheet's today. */
209	  protected readonly inForce = computed(() => {
210	    const s = this.settings();
211	    const today = this.session.today();
212	    const on = (key: DatedKey, starting: string | null) => (today === null ? starting : valueOn(s.dated[key], today, starting));
213	    return {
214	      clerkLimit: on('clerk-limit', null),
215	      floor: on('floor', DEFAULT_FLOOR),
216	      terms: on('terms', String(DEFAULT_TERMS)),
217	      termsA: on('terms-A', null),
218	      termsB: on('terms-B', null),
219	      termsC: on('terms-C', null),
220	      latePct: on('late-pct', DEFAULT_LATE_PCT),
221	      cap: on('cap', null),
222	    };
223	  });
224	  protected readonly roleError = signal<string | null>(null);
225	  protected readonly settingsError = signal<string | null>(null);
226	  private readonly busy = signal(false);
227	  /** The setting a person went into last; the clerk limit until they go into one. */
228	  private lastField: keyof SettingsFormValue | FromField = 'clerkLimit';
229	  /** Settings saves, sent one after another in the order they were made, so none is lost while another is
230	   * waiting on the server. */
231	  private readonly saves = new Subject<{
232	    sheetId: string;
233	    changed: Parameters<SettingsApi['save']>[1];
234	    sent: SettingsFormValue & Record<FromField, string>;
235	  }>();
236	  protected readonly roleForm = new FormGroup({
237	    user: new FormControl('', { nonNullable: true }),
238	    role: new FormControl('', { nonNullable: true }),
239	  });
240	  protected readonly settingsForm = new FormGroup({
241	    clerkLimit: new FormControl('', { nonNullable: true }),
242	    floor: new FormControl(DEFAULT_FLOOR, { nonNullable: true }),
243	    terms: new FormControl(String(DEFAULT_TERMS), { nonNullable: true }),
244	    termsA: new FormControl('', { nonNullable: true }),
245	    termsB: new FormControl('', { nonNullable: true }),
246	    termsC: new FormControl('', { nonNullable: true }),
247	    latePct: new FormControl(DEFAULT_LATE_PCT, { nonNullable: true }),
248	    policyDate: new FormControl('', { nonNullable: true }),
249	    periodNumberingFrom: new FormControl('', { nonNullable: true }),
250	    cap: new FormControl('', { nonNullable: true }),
251	    clerkLimitFrom: new FormControl('', { nonNullable: true }),
252	    floorFrom: new FormControl('', { nonNullable: true }),
253	    termsFrom: new FormControl('', { nonNullable: true }),
254	    termsAFrom: new FormControl('', { nonNullable: true }),
255	    termsBFrom: new FormControl('', { nonNullable: true }),
256	    termsCFrom: new FormControl('', { nonNullable: true }),
257	    latePctFrom: new FormControl('', { nonNullable: true }),
258	    capFrom: new FormControl('', { nonNullable: true }),
259	  });
260	
261	  constructor() {
262	    this.roleForm.valueChanges.subscribe(() => this.roleError.set(null));
263	    this.settingsForm.valueChanges.subscribe(() => this.settingsError.set(null));
264	    this.saves
265	      .pipe(
266	        concatMap(({ sheetId, changed, sent }) =>
267	          this.api.save(sheetId, changed).pipe(
268	            map((s) => ({ sheetId, sent, s })),
269	            catchError(() => of({ sheetId, sent, s: null })),
270	          ),
271	        ),
272	      )
273	      .subscribe(({ sheetId, sent, s }) => {
274	        if (s === null) {
275	          this.settingsError.set('Could not save the settings.');
276	        } else if (this.session.sheetId() === sheetId) {
277	          this.showSettings(s, sent);
278	        }
279	      });
280	    // Re-read the sheet's settings from the store each time a sheet is loaded.
281	    const loaded = this.session.registerLoader(inject(DestroyRef));
282	    toObservable(this.session.sheetId)
283	      .pipe(
284	        switchMap((id) =>
285	          id
286	            ? forkJoin({ id: of(id), roles: this.api.roles(id), settings: this.api.get(id) })
287	            : of({ id, roles: [] as RoleGiven[], settings: NO_SETTINGS }),
288	        ),
289	      )
290	      .subscribe(({ id, roles, settings }) => {
291	        this.roles.set(roles);
292	        this.showSettings(settings);
293	        this.roleError.set(null);
294	        this.settingsError.set(null);
295	        loaded(id);
296	      });
297	  }
298	
299	  protected setRole(): void {
300	    if (this.busy()) return;
301	    this.roleError.set(null);
302	    const sheetId = this.session.sheetId();
303	    if (!sheetId) {
304	      this.roleError.set('Load a sheet first.');
305	      return;
306	    }
307	    const user = this.roleForm.getRawValue().user.trim();
308	    const role = this.roleForm.getRawValue().role.trim();
309	    if (!user) {
310	      this.roleError.set('Type a user name.');
311	      return;
312	    }
313	    if (!(ROLES as readonly string[]).includes(role)) {
314	      this.roleError.set(`A role is ${this.roleNames}.`);
315	      return;
316	    }
317	    this.busy.set(true);
318	    this.api.setRole(sheetId, user, role).subscribe({
319	      next: (given) => {
320	        this.busy.set(false);
321	        if (this.session.sheetId() !== sheetId) return;
322	        this.roles.update((rs) =>
323	          rs.some((r) => r.user === given.user)
324	            ? rs.map((r) => (r.user === given.user ? given : r))
325	            : [...rs, given],
326	        );
327	        this.roleForm.reset({ user: '', role: '' }, { emitEvent: false });
328	      },
329	      error: () => {
330	        this.busy.set(false);
331	        this.roleError.set('Could not set that role.');
332	      },
333	    });
334	  }
335	
336	  /** The setting holding a grade's own terms. */
337	  protected gradeKey(grade: (typeof GRADES)[number]): GradeTermsKey {
338	    return `terms${grade}`;
339	  }
340	
341	  /** Note the setting a person went into last: a save with nothing changed saves that one again. */
342	  protected focused(event: FocusEvent): void {
343	    const name = (event.target as Element | null)?.getAttribute('formcontrolname');
344	    if (name && name in this.settingsForm.controls) this.lastField = name as keyof SettingsFormValue | FromField;
345	  }
346	
347	  protected save(): void {
348	    this.settingsError.set(null);
349	    const sheetId = this.session.sheetId();
350	    if (!sheetId) {
351	      this.settingsError.set('Load a sheet first.');
352	      return;
353	    }
354	    const controls = this.settingsForm.controls;
355	    // With nothing changed, the setting last gone into is saved again as it is.
356	    const unchanged = !this.settingsForm.dirty;
357	    // A setting that carries a figure is sent too when a from-date is typed for it, or it was last gone into.
358	    const fromOf = (key: keyof SettingsFormValue) =>
359	      key in DATED_FIELDS ? controls[`${key as DatedField}From`].value.trim() : '';
360	    const send = (key: keyof SettingsFormValue) =>
361	      controls[key].dirty || fromOf(key) !== '' || (unchanged && (this.lastField === key || this.lastField === `${key}From`));
362	    const clerkLimit = controls.clerkLimit.value.trim();
363	    const floor = controls.floor.value.trim();
364	    const terms = controls.terms.value.trim();
365	    const sendFloor = send('floor');
366	    const latePct = controls.latePct.value.trim();
367	    const sendTerms = send('terms');
368	    const sendLatePct = send('latePct');
369	    const policyDate = controls.policyDate.value.trim();
370	    const sendPolicyDate = send('policyDate');
371	    const periodNumberingFrom = controls.periodNumberingFrom.value.trim();
372	    const sendPeriodNumbering = send('periodNumberingFrom');
373	    const sendLimit = send('clerkLimit');
374	    const cap = controls.cap.value.trim();
375	    const sendCap = send('cap');
376	    if (sendLimit && clerkLimit !== '' && !LIMIT.test(clerkLimit)) {
377	      this.settingsError.set('Type a clerk limit of 0.00 or more, with up to two decimals, or leave it blank.');
378	      return;
379	    }
380	    if (sendFloor && !LIMIT.test(floor)) {
381	      this.settingsError.set('Type a floor of 0.00 or more, with up to two decimals.');
382	      return;
383	    }
384	    if (sendTerms && !DAYS.test(terms)) {
385	      this.settingsError.set('Type terms of 0 or more whole days.');
386	      return;
387	    }
388	    const gradeTerms: Partial<Record<GradeTermsKey, string>> = {};
389	    for (const g of GRADES) {
390	      const key = this.gradeKey(g);
391	      if (!send(key)) continue;
392	      const days = controls[key].value.trim();
393	      if (days !== '' && !DAYS.test(days)) {
394	        this.settingsError.set(`Type terms for grade ${g} of 0 or more whole days, or leave them blank.`);
395	        return;
396	      }
397	      gradeTerms[key] = days;
398	    }
399	    if (sendLatePct && !PCT.test(latePct)) {
400	      this.settingsError.set('Type a late percent of 0.00 or more, with up to two decimals.');
401	      return;
402	    }
403	    if (sendPolicyDate && policyDate !== '' && !(DATE.test(policyDate) && !isNaN(Date.parse(policyDate)))) {
404	      this.settingsError.set('Type a policy date as yyyy-mm-dd, or leave it blank.');
405	      return;
406	    }
407	    if (
408	      sendPeriodNumbering &&
409	      periodNumberingFrom !== '' &&
410	      !(DATE.test(periodNumberingFrom) && !isNaN(Date.parse(periodNumberingFrom)))
411	    ) {
412	      this.settingsError.set('Type a period numbering date as yyyy-mm-dd, or leave it blank.');
413	      return;
414	    }
415	    if (sendCap && cap !== '' && !LIMIT.test(cap)) {
416	      this.settingsError.set('Type a cap of 0.00 or more, with up to two decimals, or leave it blank.');
417	      return;
418	    }
419	    const froms: Partial<Record<FromField, string>> = {};
420	    for (const key of Object.keys(DATED_FIELDS) as DatedField[]) {
421	      const from = fromOf(key);
422	      if (!send(key) || from === '') continue;
423	      if (!(DATE.test(from) && !isNaN(Date.parse(from)))) {
424	        this.settingsError.set('Type a from-date as yyyy-mm-dd, or leave it blank for the sheet\'s today.');
425	        return;
426	      }
427	      froms[`${key}From`] = from;
428	    }
429	    const changed = {
430	      ...(sendLimit ? { clerkLimit } : {}),
431	      ...(sendFloor ? { floor } : {}),
432	      ...(sendTerms ? { terms } : {}),
433	      ...gradeTerms,
434	      ...(sendLatePct ? { latePct } : {}),
435	      ...(sendPolicyDate ? { policyDate } : {}),
436	      ...(sendPeriodNumbering ? { periodNumberingFrom } : {}),
437	      ...(sendCap ? { cap } : {}),
438	      ...froms,
439	    };
440	    this.saves.next({ sheetId, changed, sent: this.settingsForm.getRawValue() });
441	  }
442	
443	  /** Show the settings in force, and put them back in the form as unchanged; after a save (`sent` the form as
444	   * it was saved), a setting changed in the form since is left as it was typed. */
445	  private showSettings(s: SheetSettings, sent?: SettingsFormValue & Record<FromField, string>): void {
446	    this.settings.set(s);
447	    this.floor.set(s.dated.floor);
448	    this.latePct.set(s.dated['late-pct']);
449	    this.policyDate.set(s.policyDate);
450	    this.cap.set(s.dated.cap);
451	    const shown: SettingsFormValue = {
452	      clerkLimit: s.clerkLimit ?? '',
453	      floor: s.floor,
454	      terms: String(s.terms),
455	      termsA: s.termsA === null ? '' : String(s.termsA),
456	      termsB: s.termsB === null ? '' : String(s.termsB),
457	      termsC: s.termsC === null ? '' : String(s.termsC),
458	      latePct: s.latePct,
459	      policyDate: s.policyDate ?? '',
460	      periodNumberingFrom: s.periodNumberingFrom ?? '',
461	      cap: s.cap ?? '',
462	    };
463	    const controls = this.settingsForm.controls;
464	    for (const key of Object.keys(shown) as (keyof SettingsFormValue)[]) {
465	      if (!sent || controls[key].value === sent[key]) controls[key].reset(shown[key], { emitEvent: false });
466	    }
